<style>
.public-page{background:#f8f9fa;color:#0a172d;min-height:75vh}.public-page .page-wrap{width:min(1520px,92%);margin:auto}.public-page .crumb{padding:15px 0;background:white;color:#69788d}.crumb a{color:#69788d;text-decoration:none}.public-page .page-hero{background:linear-gradient(110deg,#bd1b1b,#991b1b);color:white;padding:42px 0}.page-hero h1{font-size:clamp(28px,3vw,40px);font-weight:800;margin:0 0 10px}.page-hero p{font-size:20px;margin:0}.public-page .page-section{padding:64px 0}.public-page .white-section{background:white}.public-page .page-heading{text-align:center;margin-bottom:52px}.page-heading h2{font-weight:800;font-size:36px}.page-heading p{color:#69788d;font-size:19px}.public-page .page-grid{display:grid;gap:28px;grid-template-columns:repeat(3,minmax(0,1fr))}.public-page .page-card{padding:32px;background:white;border:1px solid #edf0f3;border-radius:22px;box-shadow:0 2px 3px #10182808}.page-card h2,.page-card h3{font-size:23px;font-weight:750;margin:20px 0 16px}.page-card p{color:#52637a;line-height:1.7;font-size:18px;margin:0}.page-card a{color:#de242b;text-decoration:none}.public-page .page-icon{display:grid;place-items:center;width:70px;height:70px;border-radius:20px;background:#fff2f3;color:#ed232a;font-size:34px}.public-page .vision-icon{background:#eff6ff;color:#2465ed}.public-page .mission-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.mission-grid .page-card{padding:40px}.public-page .values-grid{grid-template-columns:repeat(4,minmax(0,1fr));text-align:center}.values-grid .page-icon{margin:auto}.values-grid h3{font-size:21px}.values-grid p{font-size:17px}.public-page .filter-tabs{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-bottom:30px}.filter-tabs a{padding:9px 22px;border-radius:40px;background:white;color:#52637a;text-decoration:none}.filter-tabs a.active{background:#e5232b;color:white}.public-page .empty-list{text-align:center;padding:75px 20px;color:#69788d}.public-page .mission-cta{background:linear-gradient(110deg,#e32226,#991b1b);color:white;text-align:center;padding:76px 20px}.mission-cta h2{font-size:38px;font-weight:800}.mission-cta p{font-size:20px;margin:16px 0 32px}.mission-cta a{display:inline-block;padding:16px 30px;border:2px solid white;border-radius:11px;color:white;text-decoration:none;font-weight:700;margin:5px}.mission-cta a:first-child{background:white;color:#e5232b}.public-page .blog-search{display:flex;gap:10px;max-width:670px;margin-top:30px}.blog-search input{min-width:0;flex:1;padding:16px;border:0;border-radius:10px}.blog-search button{border:1px solid white;border-radius:10px;background:transparent;color:white;padding:10px 20px}.public-page .journey-list{max-width:900px;margin:auto;border-left:2px solid #f4b9be;padding-left:35px}.journey-list article{position:relative;margin:0 0 30px}.journey-list article:before{content:'';position:absolute;left:-43px;top:7px;width:14px;height:14px;border-radius:50%;background:#e5232b}.journey-list h3{font-size:21px;font-weight:750}.journey-list p{color:#52637a;line-height:1.7}.public-page a:focus-visible,.public-page button:focus-visible{outline:3px solid #2165eb;outline-offset:4px}
