@media(max-width:650px){.public-page .page-grid{grid-template-columns:1fr}.public-page .page-section{padding:40px 0}.mission-grid .page-card{padding:25px}.page-heading h2{font-size:28px}.page-hero p{font-size:17px}.public-page .blog-search{flex-wrap:wrap}}
</style>
